package dev.atqiya.ledgerly.ledger.domain;
import static org.junit.jupiter.api.Assertions.*; import dev.atqiya.ledgerly.identity.domain.AppUser; import dev.atqiya.ledgerly.workspace.domain.Workspace; import java.math.BigDecimal; import java.time.*; import java.util.UUID; import org.junit.jupiter.api.Test;
class LedgerTransactionTest{
 @Test void voidPreservesAmountAndPreventsFurtherMutation(){Instant now=Instant.parse("2026-10-09T00:00:00Z");AppUser user=new AppUser(UUID.randomUUID(),"owner@test.dev","Owner","hash",now);Workspace workspace=new Workspace(UUID.randomUUID(),"Studio","studio","IDR","Asia/Jakarta",user,now);LedgerTransaction transaction=new LedgerTransaction(UUID.randomUUID(),workspace,null,TransactionType.EXPENSE,new BigDecimal("50000"),"IDR",LocalDate.parse("2026-10-09"),"Software subscription",null,user,now);transaction.voidTransaction("Duplicate entry",user,now.plusSeconds(1));assertEquals(TransactionStatus.VOIDED,transaction.getStatus());assertEquals(new BigDecimal("50000"),transaction.getAmount());assertThrows(IllegalStateException.class,()->transaction.update(null,BigDecimal.ONE,LocalDate.parse("2026-10-09"),"Changed",null,user,now.plusSeconds(2)));}
}
